task find_lucas(n: int) returns (r: int)
  requires n >= 0
  ensures r == lucas(n)
{
  if n == 0 {
    r := 2;
  } else {
    if n == 1 {
      r := 1;
    } else {
      var a: int := 2;
      var b: int := 1;
      var i: int := 2;
      while i < n
        invariant 2 <= i and i <= n
        invariant a == lucas(i - 2)
        invariant b == lucas(i - 1)
        decreases n - i
      {
        var c: int := a + b;
        a := b;
        b := c;
        i := i + 1;
      }
      r := b;
    }
  }
}
